  countries: {
    ABI: `${host}/countries/rounded_flags/ABI.png`,
    USA: `${host}/countries/rounded_flags/USA.png`,
    BRA: `${host}/countries/rounded_flags/BRA.png`,
    MEX: `${host}/countries/rounded_flags/MEX.png`,
    CHN: `${host}/countries/rounded_flags/CHN.png`,
    COL: `${host}/countries/rounded_flags/COL.png`,
    ZAF: `${host}/countries/rounded_flags/ZAF.png`,
    ARG: `${host}/countries/rounded_flags/ARG.png`,
    BOL: `${host}/countries/rounded_flags/BOL.png`,
    KOR: `${host}/countries/rounded_flags/KOR.png`,
    ECU: `${host}/countries/rounded_flags/ECU.png`,
    PER: `${host}/countries/rounded_flags/PER.png`,
    PRT: `${host}/countries/rounded_flags/PRT.png`,
    FRA: `${host}/countries/rounded_flags/FRA.png`,
    CAN: `${host}/countries/rounded_flags/CAN.png`,
    BEL: `${host}/countries/rounded_flags/BEL.png`,
    DEU: `${host}/countries/rounded_flags/DEU.png`,
  },
} as const;
